package client

import (
	"context"
	"fmt"
	"time"

	"github.com/cloudwego/kitex/pkg/endpoint"
	"github.com/cloudwego/kitex/pkg/utils"
)

// WithUnaryOptions allows grouping multiple UnaryOptions and applying them as a single Option.
func WithUnaryOptions(opts ...UnaryOption) Option {
	return Option{F: func(o *Options, di *utils.Slice) {
		for _, opt := range opts {
			opt.F(o, di)
		}
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout specifically for unary calls.
func WithUnaryRPCTimeout(d time.Duration) UnaryOption {
	return UnaryOption{Option{F: func(o *Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%s)", d))
		o.Configs.RPCTimeout = d
	}}}
}

// WithUnaryConnectTimeout sets the connection timeout specifically for unary calls.
func WithUnaryConnectTimeout(d time.Duration) UnaryOption {
	return UnaryOption{Option{F: func(o *Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryConnectTimeout(%s)", d))
		o.Configs.ConnectTimeout = d
	}}}
}

// WithUnaryMiddleware adds a unary middleware for unary calls.
func WithUnaryMiddleware(mw endpoint.UnaryMiddleware) UnaryOption {
	mwb := func(ctx context.Context) endpoint.UnaryMiddleware {
		return mw
	}
	return UnaryOption{Option{F: func(o *Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%+v)", utils.GetFuncName(mw)))
		o.UnaryMWBs = append(o.UnaryMWBs, mwb)
	}}}
}

// WithUnaryMiddlewareBuilder adds a unary middleware builder that depends on context for unary calls.
func WithUnaryMiddlewareBuilder(mwb endpoint.UnaryMiddlewareBuilder) UnaryOption {
	return UnaryOption{Option{F: func(o *Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddlewareBuilder(%+v)", utils.GetFuncName(mwb)))
		o.UnaryMWBs = append(o.UnaryMWBs, mwb)
	}}}
}
